// for open source users. It downgrades the existing admin role and migrates
// all users and trusted cluster mappings to it. This function can be called
// multiple times.
// DELETE IN(7.0)
func migrateOSS(ctx context.Context, asrv *Server) error {
	if modules.GetModules().BuildType() != modules.BuildOSS {
		return nil
	}
	adminRole, err := asrv.GetRole(teleport.AdminRoleName)
	if err != nil {
		return trace.Wrap(err, migrationAbortedMessage)
	}
	if _, ok := adminRole.GetMetadata().Labels[teleport.OSSMigratedV6]; ok {
		log.Debug("Admin role was already migrated to OSS RBAC.")
		return nil
	}
	role := services.NewDowngradedOSSAdminRole()
	log.Info("Enabling RBAC in OSS Teleport. Migrating users, roles and trusted clusters.")
	// Downgrade admin before moving users from ossuser so they cannot regain
	// full admin permissions during the migration. Leave the completion label
	// unset until every resource has been updated, allowing a failed migration
	// to be retried on the next startup.
	delete(role.GetMetadata().Labels, teleport.OSSMigratedV6)
	if err := asrv.UpsertRole(ctx, role); err != nil {
		return trace.Wrap(err, migrationAbortedMessage)
	}

	migratedUsers, err := migrateOSSUsers(ctx, role, asrv)
	if err != nil {
		return trace.Wrap(err, migrationAbortedMessage)
	}

	migratedTcs, err := migrateOSSTrustedClusters(ctx, role, asrv)
	if err != nil {
		return trace.Wrap(err, migrationAbortedMessage)
	}

	migratedConns, err := migrateOSSGithubConns(ctx, role, asrv)
	if err != nil {
		return trace.Wrap(err, migrationAbortedMessage)
	}

	// The label on the admin role marks the migration complete.
	role.GetMetadata().Labels[teleport.OSSMigratedV6] = types.True
	if err := asrv.UpsertRole(ctx, role); err != nil {
		return trace.Wrap(err, migrationAbortedMessage)
	}
	log.Infof("Migration completed. Updated admin role, %v users, %v trusted clusters and %v Github connectors.",
		migratedUsers, migratedTcs, migratedConns)

	return nil
}

const remoteWildcardPattern = "^.+$"

// migrateOSSTrustedClusters updates role mappings in trusted clusters
// OSS Trusted clusters had no explicit mapping from remote roles, to local roles.
// Map all remote roles to the local admin role.
 M lib/auth/auth_with_roles.go
 M lib/auth/init.go
 M lib/auth/init_test.go
 M lib/services/role.go
 M lib/services/role_test.go
 M tool/tctl/common/user_command.go

